package com.bank.txn.demo;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class ProcessingDemo {

    private static final Logger log = Logger.getLogger("TxnProcessing");
    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // The STREAM path reacts to each event the instant it arrives.
        FraudStreamProcessor stream = new FraudStreamProcessor(new BigDecimal("500000"));

        // The BATCH path waits for the whole day, then runs once.
        List<Transaction> dayStore = new ArrayList<>();

        List<Transaction> feed = List.of(
            new Transaction("TXN-1", "SAV2001", new BigDecimal("20000"), "UPI"),
            new Transaction("TXN-2", "SAV2001", new BigDecimal("750000"), "WIRE"),
            new Transaction("TXN-3", "CUR3001", new BigDecimal("50000"), "NEFT"),
            new Transaction("TXN-4", "CUR3001", new BigDecimal("600000"), "WIRE"),
            new Transaction("TXN-5", "SAV2001", new BigDecimal("30000"), "UPI")
        );

        log.info("=== STREAM path: one event at a time, immediate reaction ===");
        for (Transaction t : feed) {
            stream.onEvent(t);   // low latency: scored right now
            dayStore.add(t);     // also persisted for the batch path
        }

        log.info("=== BATCH path: end of day, whole bounded set at once ===");
        EndOfDayBatchJob batch = new EndOfDayBatchJob();
        Map<String, BigDecimal> totals = batch.run(dayStore);
        totals.forEach((acc, total) ->
            log.info(() -> "End-of-day total account=" + acc + " amount=Rs." + total));
    }
}

