class Transaction {
    final String txnId;
    final String accountId;
    final BigDecimal amount;
    final String channel;
    Transaction(String txnId, String accountId, BigDecimal amount, String channel) {
        this.txnId = txnId;
        this.accountId = accountId;
        this.amount = amount;
        this.channel = channel;
    }
}

// ─── Would be in FraudStreamProcessor.java ───
// Stream processing: unbounded feed, react per event with low latency.
class FraudStreamProcessor {
    private static final Logger log = Logger.getLogger("TxnProcessing");
    private final BigDecimal threshold;
    FraudStreamProcessor(BigDecimal threshold) { this.threshold = threshold; }

    void onEvent(Transaction t) {
        // This runs the instant the event arrives — milliseconds, not hours.
        if (t.amount.compareTo(threshold) > 0) {
            log.warning(() -> "FRAUD ALERT txn=" + t.txnId + " account=" + t.accountId
                    + " amount=Rs." + t.amount + " channel=" + t.channel
                    + " (blocked for review)");
        } else {
            log.fine(() -> "scored ok txn=" + t.txnId + " amount=Rs." + t.amount);
        }
    }
}

// ─── Would be in EndOfDayBatchJob.java ───
// Batch processing: bounded set, run once, optimise for throughput + completeness.
class EndOfDayBatchJob {
    private static final Logger log = Logger.getLogger("TxnProcessing");

    Map<String, BigDecimal> run(List<Transaction> wholeDay) {
        log.info(() -> "batch starting over " + wholeDay.size() + " transactions");
        Map<String, BigDecimal> totals = new LinkedHashMap<>();
        for (Transaction t : wholeDay) {
            totals.merge(t.accountId, t.amount, BigDecimal::add);
        }
        log.info("batch finished, authoritative totals computed");
        return totals;
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
